var wi = class YDr {
    constructor(e) {
        this.confusableDictionary = e
    }
    static getInstance(e) {
        return YDr.cache.get(Array.from(e))
    }
    static getLocales() {
        return YDr._locales.value
    }
    isAmbiguous(e) {
        return this.confusableDictionary.has(e)
    }
    containsAmbiguousCharacter(e) {
        for (let t = 0; t < e.length; t++) {
            const o = e.codePointAt(t);
            if (typeof o == "number" && this.isAmbiguous(o)) return !0
        }
        return !1
    }
    getPrimaryConfusable(e) {
        return this.confusableDictionary.get(e)
    }
    getConfusableCodePoints() {
        return new Set(this.confusableDictionary.keys())
    }
};
